fig = plt.gcf(); fig.set_size_inches(5.6, 3.4); ax = plt.gca()
def number(x0, tens, ones, col, fc):
    for t in range(tens):
        for k in range(10):
            ax.add_patch(plt.Rectangle((x0 + t * 0.6, k * 0.4), 0.4, 0.4, fc=fc, ec=col, lw=0.8))
    for o in range(ones):
        ax.add_patch(plt.Rectangle((x0 + tens * 0.6 + 0.3 + (o % 2) * 0.5, (o // 2) * 0.5), 0.4, 0.4, fc=fc, ec=col, lw=0.8))
number(0.0, 5, 6, 'blue', '#cfe0ff')
number(6.0, 2, 6, 'green', '#d8f0d8')
ax.text(2.2, -0.35, '56: 5 tens and 6 ones', ha='center', va='top')
