fig = plt.gcf(); fig.set_size_inches(7.0, 3.4); ax = plt.gca()
def hundred(x, y, col, fc):
    ax.add_patch(plt.Rectangle((x, y), 2.0, 2.0, fc=fc, ec=col, lw=1.0))
    for i in range(1, 10):
        ax.plot([x + 0.2 * i, x + 0.2 * i], [y, y + 2.0], color=col, lw=0.6)
        ax.plot([x, x + 2.0], [y + 0.2 * i, y + 0.2 * i], color=col, lw=0.6)
def ten(x, y, col, fc):
    ax.add_patch(plt.Rectangle((x, y), 0.2, 2.0, fc=fc, ec=col, lw=1.0))
    for i in range(1, 10):
        ax.plot([x, x + 0.2], [y + 0.2 * i, y + 0.2 * i], color=col, lw=0.6)
def one(x, y, col, fc):
    ax.add_patch(plt.Rectangle((x, y), 0.2, 0.2, fc=fc, ec=col, lw=1.0))
# 261 in blue
for h in range(2): hundred(0.0 + h * 2.2, 0.0, 'blue', '#cfe0ff')
for t in range(6): ten(4.6 + t * 0.35, 0.0, 'blue', '#cfe0ff')
one(6.9, 0.0, 'blue', '#cfe0ff')
